mapper.update:
UPDATE sys_file SET biz_type = 'HR_TRAINING_AGREEMENT', biz_id = #{enrollmentId}, file_hash = #{hash}
WHERE tenant_id = #{tenantId} AND file_id = #{fileId} AND file_type = 'HR_TRAINING_AGREEMENT'
  AND deleted = 0 AND biz_type IS NULL AND biz_id IS NULL AND url = '' AND create_by = #{uploader}

UPDATE sys_file SET biz_type = 'HR_TRAINING_RECOVERY', biz_id = #{recoveryId}
WHERE tenant_id = #{tenantId} AND file_id = #{fileId} AND file_type = 'HR_TRAINING_AGREEMENT'
  AND biz_type = 'HR_TRAINING_AGREEMENT' AND biz_id = #{enrollmentId} AND create_by = #{uploader}
  AND deleted = 0 AND url = ''

mapper.select:
SELECT file_id FROM sys_file WHERE tenant_id = #{tenantId} AND file_type = 'HR_TRAINING_AGREEMENT'
  AND biz_type = 'HR_TRAINING_AGREEMENT' AND biz_id = #{enrollmentId} AND file_hash = #{hash}
  AND create_by = #{uploader} AND deleted = 0 AND url = '' ORDER BY file_id LIMIT 1

SELECT recovery.recovery_id FROM hr_training_recovery recovery
JOIN sys_file file ON file.tenant_id = recovery.tenant_id AND file.file_id = recovery.agreement_file_id
WHERE recovery.tenant_id = #{tenantId} AND recovery.enrollment_id = #{enrollmentId}
  AND file.file_type = 'HR_TRAINING_AGREEMENT' AND file.file_hash = #{hash}
ORDER BY recovery.recovery_id LIMIT 1

mapper.update:
UPDATE hr_training_recovery SET assessed_amount = #{record.assessedAmount}, assessment_reason = #{record.assessmentReason},
    status = #{record.status}, confirmed_by = #{record.confirmedBy}, confirmed_time = #{record.confirmedTime},
    version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND recovery_id = #{record.recoveryId} AND employee_id = #{record.employeeId}
  AND enrollment_id = #{record.enrollmentId} AND agreement_file_id = #{record.agreementFileId}
  AND status = 'DRAFT' AND collected_amount = 0 AND settlement_id IS NULL AND version = #{expectedVersion}
